-- ---------------------------------------------------------------------------
-- Row-level security
--
-- FORCE so the policy applies to the table owner too. Helper calls are wrapped in
-- (select ...) so the planner evaluates them once per query rather than once per
-- row (NFR-PRF-07).
-- ---------------------------------------------------------------------------
ALTER TABLE clinics        ENABLE ROW LEVEL SECURITY;
