-- A user may read the clinics they hold an active membership in, so that login can
-- offer the choice before any clinic context exists. Own memberships only.
CREATE POLICY clinics_read ON clinics FOR SELECT
  USING (
    id = (SELECT app_current_clinic_id())
    OR EXISTS (
      SELECT 1 FROM memberships m
       WHERE m.clinic_id = clinics.id
         AND m.user_id = (SELECT app_current_user_id())
         AND m.revoked_at IS NULL
    )
  );
--> statement-breakpoint
CREATE POLICY clinics_write ON clinics FOR UPDATE
  USING (id = (SELECT app_current_clinic_id()))
  WITH CHECK (id = (SELECT app_current_clinic_id()));

--> statement-breakpoint
-- Plans are platform reference data: readable by anyone, writable by no one
-- through the application role.
CREATE POLICY plans_read ON plans FOR SELECT USING (true);

--> statement-breakpoint
CREATE POLICY subscriptions_read ON subscriptions FOR SELECT
  USING (clinic_id = (SELECT app_current_clinic_id()));

--> statement-breakpoint
CREATE POLICY branches_read ON branches FOR SELECT
  USING (clinic_id = (SELECT app_current_clinic_id()));
--> statement-breakpoint
CREATE POLICY branches_insert ON branches FOR INSERT
  WITH CHECK (clinic_id = (SELECT app_current_clinic_id()));
--> statement-breakpoint
CREATE POLICY branches_update ON branches FOR UPDATE
  USING (clinic_id = (SELECT app_current_clinic_id()))
  WITH CHECK (clinic_id = (SELECT app_current_clinic_id()));

--> statement-breakpoint
-- A user may read their own memberships without a clinic context, so that login
-- can offer the list of clinics they belong to. Own rows only.
CREATE POLICY memberships_read ON memberships FOR SELECT
  USING (
    clinic_id = (SELECT app_current_clinic_id())
    OR user_id = (SELECT app_current_user_id())
  );
