-- A staff user sees themselves, and colleagues who share the current clinic.
-- Never the whole users table.
CREATE POLICY users_read ON users FOR SELECT
  USING (
    id = (SELECT app_current_user_id())
    OR EXISTS (
      SELECT 1 FROM memberships m
       WHERE m.user_id = users.id
         AND m.clinic_id = (SELECT app_current_clinic_id())
         AND m.revoked_at IS NULL
    )
  );
--> statement-breakpoint
CREATE POLICY users_update_self ON users FOR UPDATE
  USING (id = (SELECT app_current_user_id()))
  WITH CHECK (id = (SELECT app_current_user_id()));

