-- ---------------------------------------------------------------------------
-- Privileges (NFR-SEC-09)
--
-- Immutability is enforced at privilege level, not by policy alone. A missing
-- policy is a silent grant in some configurations; a revoked privilege fails
-- loudly and cannot be reintroduced by a migration that forgot a policy.
--
-- No DELETE is granted on any table, ever. Every table therefore needs a
-- soft-void path — `memberships.revoked_at` is the pattern.
--
-- ALTER DEFAULT PRIVILEGES is deliberately NOT used: each future migration must
-- state its own grants, so that adding an append-only table is a decision rather
-- than an inheritance.
-- ---------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'physioflow_app') THEN
    -- Production creates the role with its password out of band; this branch only
    -- guarantees the grants below have a subject.
    CREATE ROLE physioflow_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS;
  END IF;
END $$;

--> statement-breakpoint
GRANT USAGE ON SCHEMA public TO physioflow_app;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON
  clinics, subscriptions, branches, memberships, therapists, users, refresh_tokens
  TO physioflow_app;
--> statement-breakpoint
GRANT SELECT ON plans TO physioflow_app;
--> statement-breakpoint
REVOKE DELETE ON ALL TABLES IN SCHEMA public FROM physioflow_app;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION
  app_current_clinic_id(),
  app_current_user_id(),
  auth_find_user_by_identifier(text),
  auth_find_refresh_token(text),
  auth_revoke_token_family(uuid)
  TO physioflow_app;
